echo "===================================="
echo "Target: 4,631+ PMK Regulations"
echo "Source: https://jdih.kemenkeu.go.id/"
echo ""

# Create backup directory
mkdir -p kemenkeu-pmk-backup
cd kemenkeu-pmk-backup

echo "📊 ATTEMPTING SYSTEMATIC PDF DOWNLOADS..."

# PMK 2026 Documents - CRITICAL PRIORITY
declare -a PMK_2026=(
    "7:Pengelolaan_Dana_Desa_2026"
    "4:PPN_Angkutan_Udara_Idulfitri_2026"  
    "3:Standar_Biaya_Keluaran_2026"
    "2:Indikator_TKD_Perubahan_2026"
