    "120:Dana_Bagi_Hasil_2025"
    "119:DAK_Nonfisik_2025"
    "118:THT_JKK_TNI_POLRI_2025"
    "117:OrgTaker_Kemenkeu_2025"
    "116:Anggaran_Rekening_Penampung_2025"
    "115:PNBP_Kekayaan_Negara_2025"
    "114:Bantuan_Zakat_PPh_2025"
    "113:Pengembalian_Cukai_2025"
    "112:Tax_Treaty_2025"
    "111:Pengawasan_Wajib_Pajak_2025"
)

# Function to download PMK with multiple methods
download_pmk() {
    local year=$1
    local number=$2
    local filename=$3
    local url="https://jdih.kemenkeu.go.id/api/download/fullText/${year}/${number}~pmk~01.pdf"
    
    echo "Downloading PMK $number/$year: $filename"
    
    # Method 1: Basic curl
    if curl -s -o "pmk-${number}-${year}.pdf" "$url"; then
        if [ -s "pmk-${number}-${year}.pdf" ]; then
            echo "✅ Success: PMK $number/$year downloaded"
            return 0
        fi
    fi
    
    # Method 2: With user agent and headers
    if curl -s -H "User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64)" \
            -H "Accept: application/pdf" \
            -H "Referer: https://jdih.kemenkeu.go.id/" \
            -o "pmk-${number}-${year}.pdf" "$url"; then
        if [ -s "pmk-${number}-${year}.pdf" ]; then
            echo "✅ Success: PMK $number/$year downloaded (Method 2)"
            return 0
        fi
    fi
    
    # Method 3: Session-based attempt
    if curl -s -b "cookiesession1=678B2909144A8C432EBD3AD4FFA3E77B" \
            -H "User-Agent: Mozilla/5.0" \
            -o "pmk-${number}-${year}.pdf" "$url"; then
        if [ -s "pmk-${number}-${year}.pdf" ]; then
            echo "✅ Success: PMK $number/$year downloaded (Method 3)"
            return 0
        fi
    fi
    
    echo "❌ Failed: PMK $number/$year - authentication required"
    rm -f "pmk-${number}-${year}.pdf" 2>/dev/null
    return 1
}

# Process 2026 PMK Documents
